var a=`1065-singapore-chili-crab`;var n=`world-1065`;var t=`SG`;var r=`southeast-asia`;var s=4;var o=31;var l={en:`Singapore Chili Crab`,ua:`Краб у чилі по-сінгапурськи`};var c={en:`Singapore Chili Crab is a dish from Singapore prepared with garlic, serrano pepper, tomato paste, blue crab. This is a home-scale version with measured ingredients in the individual steps where they are used. Blue crab replaces Singapore-style mud crab.`,ua:`Краб у чилі по-сінгапурськи, страва кухні країни Сінгапур, яку готують із таких продуктів: часник, перець серрано, томатна паста, блакитний краб. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Синій краб замінює мангрового краба для сінгапурської версії.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`garlic`,5,`clove`],[`ground-ginger`,35,`g`],[`serrano-pepper`,3,`pcs`],[`canola-oil`,55,`ml`],[`tomato-paste`,65,`g`]]},{en:`Add the cleaned, cracked crab pieces directly to the bubbling chili sauce, cover and simmer until the crab meat is fully opaque.`,ua:`Додайте очищені надколоті шматки краба просто в киплячий чилі-соус, накрийте й готуйте до повної непрозорості м’яса.`,t:[`stewing`],m:15,i:[[`blue-crab`,1100,`g`],[`shrimp-stock`,370,`ml`],[`chili-garlic-sauce`,90,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`chicken-egg`,2,`pcs`],[`cornstarch`,24,`g`],[`water`,60,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,45,`g`],[`cilantro`,20,`g`]]}];var d={slug:a,id:n,country:`SG`,region:r,servings:4,minutes:31,title:l,text:c,steps:g};export{t as country,d as default,n as id,o as minutes,r as region,s as servings,a as slug,g as steps,c as text,l as title};